"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[938],{8333:function(a,i,o){o.d(i,{Y:function(){return e}});let e=[{slug:"nevrologiya",iconKey:"brain",accent:"brand",name:{uz:"Nevrologiya",ru:"Неврология",en:"Neurology"},short:{uz:"Markaziy va periferik asab tizimi kasalliklari reabilitatsiyasi.",ru:"Реабилитация заболеваний центральной и периферической нервной системы.",en:"Rehabilitation of central and peripheral nervous system disorders."},intro:{uz:"Bolalardagi asab tizimi kasalliklarini erta aniqlash, davolash va kompleks reabilitatsiya.",ru:"Ранняя диагностика, лечение и комплексная реабилитация заболеваний нервной системы у детей.",en:"Early diagnosis, treatment and comprehensive rehabilitation of nervous system disorders in children."},about:{uz:"Nevrologiya bo'limi markaziy va periferik asab tizimi kasalliklari bilan og'rigan bolalarga ixtisoslashgan tibbiy yordam ko'rsatadi. Bo'lim faoliyati erta tashxis, zamonaviy klinik protokollar asosida davolash, dinamik kuzatuv hamda individual reabilitatsiya dasturlarini amalga oshirishga qaratilgan. Har bir bemorga nevrolog, reabilitolog, logoped va psixologdan iborat jamoa kompleks yondashuv asosida xizmat ko'rsatadi.",ru:"Отделение неврологии оказывает специализированную помощь детям с заболеваниями центральной и периферической нервной системы. Работа отделения направлена на раннюю диагностику, лечение по современным клиническим протоколам, динамическое наблюдение и индивидуальные программы реабилитации. Каждого пациента ведёт команда из невролога, реабилитолога, логопеда и психолога на основе комплексного подхода.",en:"The Neurology department provides specialized care for children with central and peripheral nervous system disorders. Its work focuses on early diagnosis, treatment according to modern clinical protocols, dynamic monitoring and individual rehabilitation programs. Each patient is cared for by a team of a neurologist, rehabilitation specialist, speech therapist and psychologist."},treats:{uz:["Bosh miya falaji (DSP) va perinatal asab tizimi zararlanishi oqibatlari","Psixo-nutqiy va harakat rivojlanishining kechikishi","Periferik nerv tizimi kasalliklari (neyropatiyalar)","Epilepsiya (kuzatuv va davolash nazorati)","Bosh miya jarohatlari va neyroinfeksiyalar oqibatlari"],ru:["Детский церебральный паралич (ДЦП) и последствия перинатального поражения ЦНС","Задержка психоречевого и моторного развития","Заболевания периферической нервной системы (нейропатии)","Эпилепсия (наблюдение и контроль лечения)","Последствия черепно-мозговых травм и нейроинфекций"],en:["Cerebral palsy and consequences of perinatal CNS damage","Delay in psycho-speech and motor development","Peripheral nervous system disorders (neuropathies)","Epilepsy (monitoring and treatment control)","Consequences of brain injuries and neuroinfections"]},facilities:{uz:["Qabul va ko'rik xonalari","Davolash va muolaja xonalari","Logopediya kabineti","Psixolog kabineti","LFK va kineziterapiya zali"],ru:["Приёмные и смотровые кабинеты","Лечебные и процедурные кабинеты","Кабинет логопеда","Кабинет психолога","Зал ЛФК и кинезитерапии"],en:["Reception and examination rooms","Treatment and procedure rooms","Speech therapy room","Psychologist room","Exercise therapy and kinesitherapy hall"]},methods:{uz:["Davolovchi jismoniy tarbiya (LFK) va kineziterapiya","Fizioterapiya (magnit, lazer, elektroforez)","Davolovchi massaj","Logopedik mashg'ulotlar","Psixologik qo'llab-quvvatlash","Ergoterapiya"],ru:["Лечебная физкультура (ЛФК) и кинезитерапия","Физиотерапия (магнит, лазер, электрофорез)","Лечебный массаж","Логопедические занятия","Психологическая поддержка","Эрготерапия"],en:["Therapeutic exercise (LFK) and kinesitherapy","Physiotherapy (magnet, laser, electrophoresis)","Therapeutic massage","Speech therapy sessions","Psychological support","Ergotherapy"]},staff:[{name:{uz:"Ismoilov Zohidjon Nurmanovich",ru:"Исмаилов Зохиджон Нурманович",en:"Ismoilov Zohidjon Nurmanovich"},role:{uz:"Davolash ishlari bo'yicha direktor o'rinbosari, nevropatolog",ru:"Заместитель директора по лечебной работе, невропатолог",en:"Deputy Director for Medical Affairs, neurologist"},meta:{uz:"PhD \xb7 Oliy toifali bolalar nevropatologi \xb7 EPNS, EAN a'zosi",ru:"PhD \xb7 Детский невропатолог высшей категории \xb7 Член EPNS, EAN",en:"PhD \xb7 Top-category pediatric neurologist \xb7 Member of EPNS, EAN"}}]},{slug:"ortopediya",iconKey:"bone",accent:"leaf",name:{uz:"Ortopediya",ru:"Ортопедия",en:"Orthopedics"},short:{uz:"Tug'ma va orttirilgan ortopedik kasalliklar, skolioz, bo'g'im patologiyalari.",ru:"Врождённые и приобретённые ортопедические заболевания, сколиоз, патологии суставов.",en:"Congenital and acquired orthopedic conditions, scoliosis, joint pathologies."},beds:50,intro:{uz:"Tayanch-harakat tizimi kasalliklarini davolash va funksiyani tiklash.",ru:"Лечение заболеваний опорно-двигательного аппарата и восстановление функций.",en:"Treatment of musculoskeletal disorders and functional recovery."},about:{uz:"Ortopediya-reabilitatsiya bo'limi 50 o'ringa mo'ljallangan bo'lib, tayanch-harakat tizimining tug'ma va orttirilgan kasalliklari bilan og'rigan bolalarga xizmat ko'rsatadi. Bo'limda zamonaviy diagnostika, jarrohlikdan keyingi tiklash va konservativ davolash usullari qo'llaniladi. Asosiy maqsad — bolaning harakat faolligini tiklash, og'riqni kamaytirish va hayot sifatini yaxshilash.",ru:"Ортопедо-реабилитационное отделение рассчитано на 50 коек и обслуживает детей с врождёнными и приобретёнными заболеваниями опорно-двигательного аппарата. В отделении применяются современная диагностика, послеоперационное восстановление и консервативные методы лечения. Главная цель — восстановление двигательной активности ребёнка, уменьшение боли и улучшение качества жизни.",en:"The orthopedic rehabilitation department has 50 beds and serves children with congenital and acquired musculoskeletal disorders. The department applies modern diagnostics, post-operative recovery and conservative treatment methods. The main goal is to restore the child's motor activity, reduce pain and improve quality of life."},treats:{uz:["Skolioz va qomat buzilishlari","Bo'g'imlar displaziyasi va patologiyalari","Tug'ma oyoq-qo'l nuqsonlari","Jarohat va operatsiyalardan keyingi holatlar","Tekispoylik va boshqa deformatsiyalar"],ru:["Сколиоз и нарушения осанки","Дисплазия и патологии суставов","Врождённые дефекты конечностей","Состояния после травм и операций","Плоскостопие и другие деформации"],en:["Scoliosis and posture disorders","Joint dysplasia and pathologies","Congenital limb defects","Post-trauma and post-surgery conditions","Flat feet and other deformities"]},facilities:{uz:["Qabul va ko'rik xonalari","Gipslash va muolaja xonasi","LFK va mexanoterapiya zali","Fizioterapiya kabineti","Ortopedik vositalar bilan ta'minlash"],ru:["Приёмные и смотровые кабинеты","Кабинет гипсования и процедур","Зал ЛФК и механотерапии","Кабинет физиотерапии","Обеспечение ортопедическими средствами"],en:["Reception and examination rooms","Casting and procedure room","LFK and mechanotherapy hall","Physiotherapy room","Provision of orthopedic devices"]},methods:{uz:["Davolovchi jismoniy tarbiya (LFK)","Mexanoterapiya va kineziterapiya","Fizioterapiya","Davolovchi massaj","Ortopedik korreksiya (shina, ortez)"],ru:["Лечебная физкультура (ЛФК)","Механотерапия и кинезитерапия","Физиотерапия","Лечебный массаж","Ортопедическая коррекция (шины, ортезы)"],en:["Therapeutic exercise (LFK)","Mechanotherapy and kinesitherapy","Physiotherapy","Therapeutic massage","Orthopedic correction (splints, orthoses)"]},staff:[{name:{uz:"Umarova Dilorom Shukurovna",ru:"Умарова Дилором Шукуровна",en:"Umarova Dilorom Shukurovna"},role:{uz:"Ortopediya-reabilitatsiya bo'limi mudiri",ru:"Заведующая ортопедо-реабилитационным отделением",en:"Head of Orthopedic Rehabilitation Department"},meta:{uz:"Oliy toifali shifokor, bolalar ortopedi",ru:"Врач высшей категории, детский ортопед",en:"Top-category physician, pediatric orthopedist"}}]},{slug:"revmatologiya",iconKey:"activity",accent:"brand",name:{uz:"Revmatologiya",ru:"Ревматология",en:"Rheumatology"},short:{uz:"Bo'g'imlar, suyak-mushak tizimi va biriktiruvchi to'qima kasalliklari. 1972-yildan.",ru:"Заболевания суставов, опорно-двигательного аппарата и соединительной ткани. С 1972 года.",en:"Diseases of joints, musculoskeletal system and connective tissue. Since 1972."},since:1972,intro:{uz:"Revmatologik kasalliklarni erta aniqlash, davolash va reabilitatsiya — 1972-yildan buyon.",ru:"Ранняя диагностика, лечение и реабилитация ревматологических заболеваний — с 1972 года.",en:"Early diagnosis, treatment and rehabilitation of rheumatological diseases — since 1972."},about:{uz:"Revmatologiya bo'limi 1972-yildan buyon o'z faoliyatini olib bormoqda va tayanch-harakat tizimi hamda biriktiruvchi to'qima kasalliklariga ega bemorlarga ixtisoslashgan tibbiy yordam ko'rsatib keladi. Bo'limning asosiy faoliyati revmatologik kasalliklarni erta aniqlash, zamonaviy usullar yordamida tashxis qo'yish, davolash, dinamik kuzatuv hamda reabilitatsiya tadbirlarini amalga oshirishdan iborat. Kasalliklarning asoratlarini oldini olish, bemorlar hayot sifatini yaxshilash va nogironlik darajasini kamaytirishga alohida e'tibor qaratiladi.",ru:"Отделение ревматологии работает с 1972 года и оказывает специализированную помощь пациентам с заболеваниями опорно-двигательного аппарата и соединительной ткани. Основная деятельность — ранняя диагностика ревматологических заболеваний, постановка диагноза современными методами, лечение, динамическое наблюдение и реабилитация. Особое внимание уделяется профилактике осложнений, улучшению качества жизни пациентов и снижению степени инвалидности.",en:"The Rheumatology department has been operating since 1972, providing specialized care to patients with musculoskeletal and connective tissue diseases. Its main activity is early detection of rheumatological diseases, diagnosis using modern methods, treatment, dynamic monitoring and rehabilitation. Special attention is paid to preventing complications, improving patients' quality of life and reducing disability."},treats:{uz:["Revmatoid artrit","Reaktiv artrit","Sistemali qizil yuguruk","Vaskulitlar","Podagra","Boshqa revmatologik kasalliklar"],ru:["Ревматоидный артрит","Реактивный артрит","Системная красная волчанка","Васкулиты","Подагра","Другие ревматологические заболевания"],en:["Rheumatoid arthritis","Reactive arthritis","Systemic lupus erythematosus","Vasculitis","Gout","Other rheumatological diseases"]},facilities:{uz:["Qabul va ko'rik xonalari","Davolash va muolaja xonalari","Kunduzgi statsionar","Laborator tekshiruv imkoniyatlari","Fizioterapiya va reabilitatsiya xizmatlari","Shina va ortopedik vositalardan foydalanish"],ru:["Приёмные и смотровые кабинеты","Лечебные и процедурные кабинеты","Дневной стационар","Лабораторные исследования","Физиотерапия и реабилитация","Использование шин и ортопедических средств"],en:["Reception and examination rooms","Treatment and procedure rooms","Day hospital","Laboratory testing facilities","Physiotherapy and rehabilitation services","Use of splints and orthopedic devices"]},methods:{uz:["Dori-darmon terapiyasi","BTL fizioterapiya uskunalari bilan muolajalar","Magnitoterapiya","Lazer terapiya","Elektroforez","Ultratovush terapiyasi","Parafin va ozokerit bilan davolash","Massaj va davolovchi gimnastika (LFK)"],ru:["Медикаментозная терапия","Процедуры на аппаратах физиотерапии BTL","Магнитотерапия","Лазеротерапия","Электрофорез","Ультразвуковая терапия","Лечение парафином и озокеритом","Массаж и лечебная гимнастика (ЛФК)"],en:["Drug therapy","Procedures on BTL physiotherapy equipment","Magnetotherapy","Laser therapy","Electrophoresis","Ultrasound therapy","Paraffin and ozokerite treatment","Massage and therapeutic gymnastics (LFK)"]},staff:[{name:{uz:"Saliyeva Nilufar Ravshanovna",ru:"Салиева Нилуфар Равшановна",en:"Saliyeva Nilufar Ravshanovna"},role:{uz:"Revmatologiya bo'limi mudiri",ru:"Заведующая отделением ревматологии",en:"Head of Rheumatology Department"},meta:{uz:"Bolalar revmatologi \xb7 Toshkent pediatriya tibbiyot instituti (2016), magistratura — revmatologiya (2017)",ru:"Детский ревматолог \xb7 Ташкентский педиатрический мединститут (2016), магистратура — ревматология (2017)",en:"Pediatric rheumatologist \xb7 Tashkent Pediatric Medical Institute (2016), master's — rheumatology (2017)"}},{name:{uz:"Sobirova Movjuda Sunatullayevna",ru:"Собирова Мовжуда Сунатуллаевна",en:"Sobirova Movjuda Sunatullayevna"},role:{uz:"Bo'lim katta hamshirasi",ru:"Старшая медсестра отделения",en:"Senior nurse of the department"},meta:{uz:"46 yillik mehnat tajribasiga ega malakali tibbiyot xodimi",ru:"46 лет трудового стажа, квалифицированный медицинский работник",en:"46 years of work experience, qualified medical professional"}}]},{slug:"pulmonologiya",iconKey:"wind",accent:"leaf",name:{uz:"Pulmonologiya",ru:"Пульмонология",en:"Pulmonology"},short:{uz:"Nafas yo'llari kasalliklari bo'yicha davolash va tiklash.",ru:"Лечение и восстановление при заболеваниях дыхательных путей.",en:"Treatment and recovery for respiratory tract diseases."},intro:{uz:"Nafas yo'llari kasalliklaridan keyin bolaning sog'lig'ini tiklash.",ru:"Восстановление здоровья ребёнка после заболеваний дыхательных путей.",en:"Restoring a child's health after respiratory tract diseases."},about:{uz:"Pulmonologiya bo'limi nafas yo'llari kasalliklari bilan og'rigan bolalarga davolash va reabilitatsiya xizmatlarini ko'rsatadi. Bo'limda surunkali bronxit, takroriy pnevmoniya, bronxial astma (avj olishdan tashqari) va tez-tez nafas yo'llari infeksiyalariga chalinadigan bolalar kompleks tiklash dasturidan o'tadi. Asosiy maqsad — nafas funksiyasini yaxshilash, immunitetni mustahkamlash va kasallik qaytalanishining oldini olish.",ru:"Отделение пульмонологии оказывает лечебные и реабилитационные услуги детям с заболеваниями дыхательных путей. В отделении проходят комплексную программу восстановления дети с хроническим бронхитом, повторными пневмониями, бронхиальной астмой (вне обострения) и частыми респираторными инфекциями. Главная цель — улучшение дыхательной функции, укрепление иммунитета и профилактика рецидивов.",en:"The Pulmonology department provides treatment and rehabilitation for children with respiratory tract diseases. Children with chronic bronchitis, recurrent pneumonia, bronchial asthma (outside exacerbation) and frequent respiratory infections undergo a comprehensive recovery program. The main goal is to improve respiratory function, strengthen immunity and prevent relapses."},treats:{uz:["Surunkali va takroriy bronxit","Pnevmoniyadan keyingi holatlar","Bronxial astma (avj olishdan tashqari)","Tez-tez kasallanuvchi bolalar","Yuqori nafas yo'llari surunkali kasalliklari"],ru:["Хронический и повторный бронхит","Состояния после пневмонии","Бронхиальная астма (вне обострения)","Часто болеющие дети","Хронические заболевания верхних дыхательных путей"],en:["Chronic and recurrent bronchitis","Post-pneumonia conditions","Bronchial asthma (outside exacerbation)","Frequently ill children","Chronic upper respiratory tract diseases"]},facilities:{uz:["Qabul va ko'rik xonalari","Ingalyatsiya kabineti","Galoterapiya (tuz xonasi)","Fizioterapiya kabineti","Nafas gimnastikasi zali"],ru:["Приёмные и смотровые кабинеты","Ингаляционный кабинет","Галотерапия (соляная комната)","Кабинет физиотерапии","Зал дыхательной гимнастики"],en:["Reception and examination rooms","Inhalation room","Halotherapy (salt room)","Physiotherapy room","Breathing exercise hall"]},methods:{uz:["Nafas gimnastikasi","Ingalyatsion terapiya","Galoterapiya","Fizioterapiya","Ko'krak qafasi massaji","Davolovchi jismoniy tarbiya (LFK)"],ru:["Дыхательная гимнастика","Ингаляционная терапия","Галотерапия","Физиотерапия","Массаж грудной клетки","Лечебная физкультура (ЛФК)"],en:["Breathing exercises","Inhalation therapy","Halotherapy","Physiotherapy","Chest massage","Therapeutic exercise (LFK)"]},staff:[]},{slug:"gastroenterologiya",iconKey:"stomach",accent:"brand",name:{uz:"Gastroenterologiya",ru:"Гастроэнтерология",en:"Gastroenterology"},short:{uz:"Oshqozon-ichak kasalliklari reabilitatsiyasi: dieta, rejim, harakat va dori kompleksda.",ru:"Реабилитация при заболеваниях ЖКТ: диета, режим, движение и медикаменты в комплексе.",en:"GI rehabilitation: diet, regimen, movement and medication combined."},beds:20,intro:{uz:"Oshqozon-ichak kasalliklaridan keyin organizmni tiklashga qaratilgan kompleks reabilitatsiya.",ru:"Комплексная реабилитация для восстановления организма после заболеваний ЖКТ.",en:"Comprehensive rehabilitation to restore the body after gastrointestinal diseases."},about:{uz:"Gastroenterologiya bo'limi 20 o'ringa mo'ljallangan bo'lib, 12 nafar xodim faoliyat yuritadi: bo'lim boshlig'i, katta hamshira, palata hamshiralari, kichik tibbiy xodimlar, davolash xonasi hamshirasi va ovqat tarqatuvchilar. Bo'limda asosan oshqozon-ichak kasalliklari (gastrit, xolesistit, qabziyat, oshqozon-ichak yara kasalliklari va boshqalar) bilan og'rigan bemorlar davolanadi. Reabilitatsiya — bu faqat dori emas: dieta, rejim, harakat va dori birgalikda olib boriladi. Asosiy maqsad — hazmni normallashtirish, og'riq va diskomfortni kamaytirish, ichak motorikasini yaxshilash va kasallik qaytalanishining oldini olish.",ru:"Отделение гастроэнтерологии рассчитано на 20 коек, в нём работают 12 сотрудников: заведующий отделением, старшая медсестра, палатные медсёстры, младший медперсонал, медсестра процедурного кабинета и работники по раздаче питания. В отделении лечатся преимущественно пациенты с заболеваниями ЖКТ (гастрит, холецистит, запоры, язвенная болезнь и др.). Реабилитация — это не только лекарства: диета, режим, движение и медикаменты ведутся вместе. Главная цель — нормализация пищеварения, уменьшение боли и дискомфорта, улучшение моторики кишечника и профилактика рецидивов.",en:"The Gastroenterology department has 20 beds and 12 staff members: department head, senior nurse, ward nurses, junior medical staff, procedure room nurse and catering staff. The department mainly treats patients with gastrointestinal diseases (gastritis, cholecystitis, constipation, peptic ulcer, etc.). Rehabilitation is not only medication: diet, regimen, movement and medication go together. The main goal is to normalize digestion, reduce pain and discomfort, improve intestinal motility and prevent relapses."},treats:{uz:["Gastrit","Xolesistit","Qabziyat","Oshqozon-ichak yara kasalliklari","Hazm tizimining boshqa surunkali kasalliklari"],ru:["Гастрит","Холецистит","Запоры","Язвенная болезнь желудка и кишечника","Другие хронические заболевания пищеварения"],en:["Gastritis","Cholecystitis","Constipation","Peptic ulcer of stomach and intestines","Other chronic digestive diseases"]},facilities:{uz:["20 o'rinli statsionar","Davolash xonasi","Dieta (parhez) tashkil etish","Fizioterapiya kabineti","LFK zali"],ru:["Стационар на 20 коек","Процедурный кабинет","Организация диетического питания","Кабинет физиотерапии","Зал ЛФК"],en:["20-bed inpatient ward","Procedure room","Dietary nutrition setup","Physiotherapy room","LFK hall"]},methods:{uz:["Dieta: mayda-mayda, tez-tez ovqatlanish; qovurilgan, yog'li, achchiq taomlarni cheklash","Dori vositalari: spazmolitiklar, fermentlar, laktuloza, probiotiklar, gepatoprotektorlar, prebiotiklar","LFK (oshqozon-ichak trakti uchun)","Elektromuolajalar","Suvli muolajalar","Massaj","Psixoemotsional qo'llab-quvvatlash: stress va uyqu rejimini nazorat qilish"],ru:["Диета: дробное частое питание; ограничение жареного, жирного, острого","Медикаменты: спазмолитики, ферменты, лактулоза, пробиотики, гепатопротекторы, пребиотики","ЛФК (для ЖКТ)","Электропроцедуры","Водные процедуры","Массаж","Психоэмоциональная поддержка: контроль стресса и режима сна"],en:["Diet: small frequent meals; limiting fried, fatty and spicy food","Medication: antispasmodics, enzymes, lactulose, probiotics, hepatoprotectors, prebiotics","LFK (for the GI tract)","Electrotherapy procedures","Water procedures","Massage","Psycho-emotional support: stress and sleep regimen control"]},diagnostics:{uz:["Vazn va bo'y nazorati","Qon tahlillari","Jigar va o't pufagi UZI","Koprogramma"],ru:["Контроль веса и роста","Анализы крови","УЗИ печени и желчного пузыря","Копрограмма"],en:["Weight and height monitoring","Blood tests","Ultrasound of liver and gallbladder","Coprogram"]},staff:[]},{slug:"qabul-diagnostika",iconKey:"clipboard",accent:"leaf",name:{uz:"Qabul va diagnostika",ru:"Приём и диагностика",en:"Reception & Diagnostics"},short:{uz:"Bemorlarni qabul qilish va to'liq diagnostik tekshiruv: rentgen, UZI, EEG, ENMG, EKG.",ru:"Приём пациентов и полное диагностическое обследование: рентген, УЗИ, ЭЭГ, ЭНМГ, ЭКГ.",en:"Patient reception and full diagnostic examination: X-ray, ultrasound, EEG, ENMG, ECG."},intro:{uz:"Aniq tashxis — to'g'ri reabilitatsiyaning birinchi qadami.",ru:"Точный диагноз — первый шаг правильной реабилитации.",en:"An accurate diagnosis is the first step of proper rehabilitation."},about:{uz:"Qabul-diagnostika bo'limi bemorlarni qabul qilish va diagnostik tekshirishga ixtisoslashgan. Bo'limda rentgen diagnostika, UZI, EEG, ENMG, EXOEG, EKG va laborator diagnostika tekshiruvlari olib boriladi. Shu bilan birga bo'limda oliy toifali stomatolog, otolaringolog, pediatr, oliy toifali laboratoriya shifokori, UZI shifokori, kardiolog hamda EEG va ENMG diagnostikasi bo'yicha oliy toifali nevropatolog shifokor faoliyat yuritadi.",ru:"Отделение приёма и диагностики специализируется на приёме пациентов и диагностическом обследовании. В отделении проводятся рентген-диагностика, УЗИ, ЭЭГ, ЭНМГ, ЭХОЭГ, ЭКГ и лабораторные диагностические исследования. Также в отделении работают стоматолог высшей категории, отоларинголог, педиатр, врач лаборатории высшей категории, врач УЗИ, кардиолог, а также невропатолог высшей категории по ЭЭГ- и ЭНМГ-диагностике.",en:"The Reception and Diagnostics department specializes in patient reception and diagnostic examination. It performs X-ray diagnostics, ultrasound, EEG, ENMG, EchoEG, ECG and laboratory diagnostic tests. The department also employs a top-category dentist, an otolaryngologist, a pediatrician, a top-category laboratory physician, an ultrasound physician, a cardiologist and a top-category neurologist for EEG and ENMG diagnostics."},treats:{uz:["Bemorlarni qabul qilish va saralash","Birlamchi va takroriy ko'rik","Mutaxassis shifokorlar konsultatsiyasi"],ru:["Приём и сортировка пациентов","Первичный и повторный осмотр","Консультации врачей-специалистов"],en:["Patient reception and triage","Primary and repeat examination","Specialist physician consultations"]},facilities:{uz:["Rentgen kabineti","UZI kabineti (Sonoscape S22, Esaote MyLab X6)","EEG va ENMG kabineti","EKG va EXOEG kabineti","Klinik-diagnostik laboratoriya","Stomatolog va ENT kabinetlari"],ru:["Рентген-кабинет","Кабинет УЗИ (Sonoscape S22, Esaote MyLab X6)","Кабинет ЭЭГ и ЭНМГ","Кабинет ЭКГ и ЭХОЭГ","Клинико-диагностическая лаборатория","Кабинеты стоматолога и ЛОР"],en:["X-ray room","Ultrasound room (Sonoscape S22, Esaote MyLab X6)","EEG and ENMG room","ECG and EchoEG room","Clinical diagnostic laboratory","Dentist and ENT rooms"]},methods:{uz:["Rentgen diagnostika","UZI (ultratovush) tekshiruvi","EEG — bosh miya faolligi","ENMG — nerv-mushak diagnostikasi","EKG va EXOEG","Laborator tekshiruvlar"],ru:["Рентген-диагностика","УЗИ (ультразвуковое исследование)","ЭЭГ — активность головного мозга","ЭНМГ — нервно-мышечная диагностика","ЭКГ и ЭХОЭГ","Лабораторные исследования"],en:["X-ray diagnostics","Ultrasound examination","EEG — brain activity","ENMG — neuromuscular diagnostics","ECG and EchoEG","Laboratory tests"]},staff:[{name:{uz:"Bakiyeva Inobat Bahranovna",ru:"Бакиева Инобат Бахрановна",en:"Bakiyeva Inobat Bahranovna"},role:{uz:"Qabul-diagnostika bo'limi mudiri, pediatr-reabilitolog",ru:"Заведующая отделением приёма и диагностики, педиатр-реабилитолог",en:"Head of Reception & Diagnostics, pediatrician-rehabilitologist"},meta:{uz:"Oliy toifali shifokor \xb7 Sog'liqni saqlash a'lochisi \xb7 34 yillik tajriba",ru:"Врач высшей категории \xb7 Отличник здравоохранения \xb7 34 года опыта",en:"Top-category physician \xb7 Excellence in Healthcare \xb7 34 years of experience"}},{name:{uz:"Shohaydarova Risola Yusufjanovna",ru:"Шохайдарова Рисола Юсуфжановна",en:"Shohaydarova Risola Yusufjanovna"},role:{uz:"UZI shifokori",ru:"Врач УЗИ",en:"Ultrasound physician"},meta:{uz:"6 yillik staj \xb7 A.N.Bakulev nomidagi markaz (Moskva, 2017–2019), Toshkent pediatriya instituti — radiologiya (2022–2023) \xb7 Apparatlar: Sonoscape S22, Esaote MyLab X6",ru:"Стаж 6 лет \xb7 Центр им. А.Н. Бакулева (Москва, 2017–2019), Ташкентский педиатрический институт — радиология (2022–2023) \xb7 Аппараты: Sonoscape S22, Esaote MyLab X6",en:"6 years experience \xb7 A.N. Bakulev Center (Moscow, 2017–2019), Tashkent Pediatric Institute — radiology (2022–2023) \xb7 Equipment: Sonoscape S22, Esaote MyLab X6"}}]}]},8175:function(a,i,o){function e(a,i){var o;return null!==(o=a[i])&&void 0!==o?o:a.uz}function t(a){return"".concat("/rbtrm").concat(a)}o.d(i,{p:function(){return t},tx:function(){return e}})},9656:function(a,i,o){o.d(i,{jD:function(){return u},rU:function(){return s},tv:function(){return h}});var e=o(7366),t=o(3795),r=o(257);let n=(0,e.R)({locales:["uz","ru","en"],defaultLocale:"uz",localePrefix:"true"===r.env.STATIC_EXPORT?"always":"as-needed"}),{Link:s,redirect:l,usePathname:u,useRouter:h,getPathname:d}=(0,t.os)(n)}}]);